{
  "name": "opencode-companion",
  "version": "1.0.1",
  "private": true,
  "description": "Two focused OpenCode plugins: structured prompts and OpenCode Go usage awareness.",
  "license": "MIT",
  "workspaces": [
    "plugins/*"
  ],
  "scripts": {
    "typecheck": "tsc --noEmit",
    "test": "node --import tsx --test tests/*.test.ts",
    "check": "npm run typecheck && npm test"
  },
  "devDependencies": {
    "@opencode/plugin": "^2.2.5",
    "@types/bun": "^1.3.0",
    "@types/node": "^24.0.0",
    "tsx": "^4.20.0",
    "typescript": "^5.9.0"
  }
}

{
  "$schema": "https://opencode.ai/config.json",
  "plugins": [
    {
      "package": "../plugins/prompt-craft",
      "options": {
        "enabled": true,
        "minChars": 4,
        "maxChars": 4000,
        "timeoutMs": 15000,
        "cooldownMs": 60000,
        "debug": false
      }
    },
    {
      "package": "../plugins/go-usage",
      "options": {
        "timezoneOffsetMinutes": 480,
        "peakWindows": ["09:00-12:00", "14:00-18:00"],
        "workdays": [1, 2, 3, 4, 5],
        "warnings": true
      }
    }
  ]
}

{
  "name": "opencode-companion-prompt-craft",
  "version": "1.0.1",
  "description": "OpenCode plugin that rewrites a rough request into a structured, executable prompt before it reaches the agent.",
  "type": "module",
  "license": "MIT",
  "author": "jokerXYH",
  "homepage": "https://github.com/jokerXYH/opencode-companion/tree/main/plugins/prompt-craft",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/jokerXYH/opencode-companion.git",
    "directory": "plugins/prompt-craft"
  },
  "bugs": {
    "url": "https://github.com/jokerXYH/opencode-companion/issues"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "prompt",
    "prompt-engineering",
    "prompt-rewrite",
    "ai-coding"
  ],
  "exports": {
    ".": "./index.ts"
  },
  "files": [
    "index.ts",
    "rewrite.ts",
    "README.md",
    "LICENSE"
  ],
  "dependencies": {
    "@opencode/plugin": "^2.2.5"
  }
}
